fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. In the sidebar, click the '...' (Options) menu at the top of the conversation list and choose 'Select Conversations'. Confirm the list enters selection mode: checkboxes appear next to conversations and a selection action bar appears with a count, a 'Select All' (or 'Deselect All') link, a 'Delete (N)' button, and a 'Cancel' button. Tick a checkbox and confirm the count updates. Then click 'Cancel' to exit selection mode. Seeing selection mode toggle on with its action bar is success — you do NOT need to actually delete anything. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
